package br.com.fisius.security;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.Key;import java.util.*;@Service public class JwtService{@Value("${app.jwt.secret}")private String secret;@Value("${app.jwt.expiration}")private Long expiration;private Key key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}public String gerarToken(String email){Date now=new Date();return Jwts.builder().subject(email).issuedAt(now).expiration(new Date(now.getTime()+expiration)).signWith(key()).compact();}public String extrairEmail(String token){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key()).build().parseSignedClaims(token).getPayload().getSubject();}public boolean valido(String token){try{extrairEmail(token);return true;}catch(Exception e){return false;}}}
